"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[46059],{46059:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/gomtang-1.png\\"\\n          title=\\"Gomtang 1: The Killer from the Future\\"\\n          author=\\"Kim Young-tak\\"\\n          publisher=\\"Arte\\"\\n          publishedDate=\\"2021-05-13\\"\\n          isbn=\\"9788950995454\\"\\n          rating=4\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\nThe story begins with Busan in 2063 as the background.  \\nTime travel to the past becomes possible, but it is dangerous enough to risk one\'s life.  \\nIn a world where the gap between the rich and the poor has become wider, the rich buy people who will risk their lives to go on a time travel with money.  \\nThe rich sometimes send people on time travel for important work, but they also send them on life-risking time travel because they miss the taste of ```cup noodles``` they tasted in the past.  \\n<br>\\nThe protagonist ends up on a life-risking time travel to learn the ```Gomtang``` (beef bone soup) recipe of the past.  \\n<br>\\nA bizarre murder case occurs in the time of the past, and it seems to be intertwined with people from the future.  \\n<br>\\nThe immersion of the novel is insane.  "}')}}]);